1\"\n  },\n  \"devDependencies\": {\n    \"@deepseek-ai/cordis\": \"4.0.5\",\n    \"@deepseek-ai/dsh-agent\": \"0.2.1-rc.2\",\n    \"@deepseek-ai/dsh-credentials\": \"0.2.1-rc.2\",\n    \"@deepseek-ai/dsh-llm\": \"0.2.1-rc.2\",\n    \"@deepseek-ai/dsh-session\": \"0.2.1-rc.2\",\n    \"@deepseek-ai/dsh-session-persistence\": \"0.2.1-rc.2\",\n    \"@deepseek-ai/dsh-tools\": \"0.2.1-rc.2\",\n    \"@deepseek-ai/dsh-user-approval\": \"0.2.1-rc.2\",\n    \"@deepseek-ai/dsh-user-questions\": \"0.2.1-rc.2\",\n    \"@deepseek-ai/schemastery\": \"3.18.5\",\n    \"@types/js-yaml\": \"^4.0.9\",\n    \"@types/node\": \"^22.15.0\",\n    \"@types/ws\": \"^8.5.13\",\n    \"tsx\": \"^4.20.6\",\n    \"typescript\": \"^5.9.2\"\n  },\n  \"engines\": {\n    \"node\": \">=22.19.0\"\n  },\n  \"repository\": {\n    \"type\": \"git\",\n    \"url\": \"git+https://github.com/inclusionAI/Avernet.git\",\n    \"directory\": \"apps/bcs/crates/plugins/deepseek-harness-channel-bcn\"\n  },\n  \"keywords\": [\n    \"deepseek-harness\",\n    \"dsh-plugin\",\n    \"cordis\",\n    \"bcn\",\n    \"bcs\",\n    \"multi-agent\"\n  ],\n  \"license\": \"Apache-2.0\",\n  \"publishConfig\": {\n    \"registry\": \"https://registry.npmjs.org/\",\n    \"access\": \"public\"\n  }\n}\n"
